<?php
session_start();
require_once __DIR__.'/../php/sd_authorization.php';
sdRequireRole('technician');
require_once '../php/conexao.php';require_once '../php/sd_service.php';
if(empty($_SESSION['sd_admin_csrf']))$_SESSION['sd_admin_csrf']=bin2hex(random_bytes(24));$msg='';
try{
 sdSchema($conexao);
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals($_SESSION['sd_admin_csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('CSRF inválido');
  sdUpdate($conexao,(int)($_POST['id']??0),(string)($_POST['status']??''),mb_substr(trim((string)($_POST['assigned_to']??'')),0,130),(string)($_POST['note']??''),(string)($_SESSION['username']??$_SESSION['user_id']??'tecnico'));
  $msg='Chamado atualizado.';
 }
 $originFilter=(string)($_GET['origin']??'todos');if(!in_array($originFilter,['todos','manual','iot'],true))$originFilter='todos';
 $priorityFilter=(string)($_GET['priority']??'todos');if(!in_array($priorityFilter,['todos','baixa','media','alta','critica'],true))$priorityFilter='todos';
 $statusFilter=(string)($_GET['status']??'todos');if(!in_array($statusFilter,['todos','aberto','em_atendimento','aguardando','resolvido','fechado'],true))$statusFilter='todos';
 $search=trim((string)($_GET['q']??'')); $search=mb_substr($search,0,100);
 $assignee=trim((string)($_GET['assignee']??''));$assignee=mb_substr($assignee,0,130);
 $slaFilter=(string)($_GET['sla']??'todos');if(!in_array($slaFilter,['todos','violado','proximo','normal'],true))$slaFilter='todos';
 $sql='SELECT id,protocol,origin,title,priority,status,assigned_to,created_at,first_response_at,resolved_at,TIMESTAMPDIFF(MINUTE,created_at,COALESCE(first_response_at,NOW())) AS response_minutes,TIMESTAMPDIFF(MINUTE,created_at,COALESCE(resolved_at,NOW())) AS resolution_minutes FROM sd_tickets WHERE (? = \'todos\' OR origin = ?) AND (? = \'todos\' OR priority = ?) AND (? = \'todos\' OR status = ?) AND (? = \'\' OR protocol LIKE ? OR title LIKE ? OR device_id LIKE ?) AND (? = \'\' OR assigned_to LIKE ?) ORDER BY created_at DESC LIMIT 300';
 $list=$conexao->prepare($sql);$pattern='%'.addcslashes($search,'%_\\').'%';$person='%'.addcslashes($assignee,'%_\\').'%'; $list->bind_param('ssssssssssss',$originFilter,$originFilter,$priorityFilter,$priorityFilter,$statusFilter,$statusFilter,$search,$pattern,$pattern,$pattern,$assignee,$person);$list->execute();$tickets=$list->get_result()->fetch_all(MYSQLI_ASSOC);$list->close();
 $violations=0;$near=0; foreach($tickets as &$ticket){
  $ticket['sla']=sdSlaStatus($ticket);$late=$ticket['sla']['response_breached'] || $ticket['sla']['resolution_breached'];
  $open=!in_array($ticket['status'],['resolvido','fechado'],true);
  $deadline=$ticket['first_response_at']? $ticket['sla']['resolution_deadline'] : min($ticket['sla']['response_deadline'],$ticket['sla']['resolution_deadline']);
  $minutes=(strtotime($deadline)-time())/60;
  $ticket['urgency']=$late?'violado':($open&&$minutes>=0&&$minutes<=30?'proximo':'normal');
  if($late)$violations++;if($ticket['urgency']==='proximo')$near++;
 } unset($ticket);
 if($slaFilter!=='todos')$tickets=array_values(array_filter($tickets,static fn($row)=>$row['urgency']===$slaFilter));
 $sla=$conexao->query("SELECT COUNT(*) total, SUM(status IN ('aberto','em_atendimento','aguardando')) pending, SUM(origin='iot') iot, ROUND(AVG(IF(first_response_at IS NOT NULL,TIMESTAMPDIFF(MINUTE,created_at,first_response_at),NULL)),1) avg_response_min, ROUND(AVG(IF(resolved_at IS NOT NULL,TIMESTAMPDIFF(MINUTE,created_at,resolved_at),NULL)),1) avg_resolution_min FROM sd_tickets")->fetch_assoc();
}catch(Throwable $e){$msg='Erro: '. $e->getMessage();$tickets=[];$sla=[];}
function sdH($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Service Desk | Gestão</title><link rel="stylesheet" href="../assets/css/sd.css"><link rel="stylesheet" href="../assets/css/confinter-sd-refinement.css"><link rel="stylesheet" href="assets/css/confinter-operations-2026.css"><link rel="stylesheet" href="assets/css/admin-ui.css"><link rel="stylesheet" href="assets/css/confinter-operations-2026.css"><style>.v5-filter-tools{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.v5-filter-tools button{border:1px solid #bfd2e3;border-radius:8px;background:#f3f8ff;padding:8px 12px;color:#174a78;cursor:pointer}.v5-filter-tools small{align-self:center}</style><script src="assets/js/confinter-v5-filters.js" defer></script></head><body><?php include __DIR__.'/navbar.php';  ?><div class="page-wrapper"><main class="sd-wrap sd-admin-surface"><header><a href="admin.php">← Administração</a><h1>Service Desk — Gestão e SLA</h1><p>Chamados manuais e incidentes gerados pela IoT. Metas de SLA em minutos corridos, configuráveis por ambiente.</p></header><?php if($msg):?><p role="status" class="notice"><?=sdH($msg)?></p><?php endif;?><div class="sd-metrics"><article><strong><?=sdH($sla['total']??0)?></strong><span>Total</span></article><article><strong><?=sdH($sla['pending']??0)?></strong><span>Em aberto</span></article><article><strong><?=sdH($sla['iot']??0)?></strong><span>Origem IoT</span></article><article><strong><?=sdH($sla['avg_response_min']??'—')?></strong><span>Resposta média (min)</span></article><article><strong><?=sdH($sla['avg_resolution_min']??'—')?></strong><span>Resolução média (min)</span></article><article><strong><?=sdH($violations??0)?></strong><span>Com prazo excedido (últimos 100)</span></article></div><section class="sd-card"><h2>Alertas operacionais</h2><p role="status"><strong><?=sdH($violations??0)?></strong> chamados vencidos e <strong><?=sdH($near??0)?></strong> próximos do limite nos últimos 300 chamados consultados (antes do filtro de SLA). Alertas calculados na abertura desta página; não representam notificações em tempo real.</p><p><a href="service-desk-produtividade.php">Relatório de produtividade técnica →</a> · <a href="iot-monitoramento.php">Monitoramento de dispositivos →</a></p></section><section class="sd-card"><h2>Filtros de atendimento</h2><form method="get" style="display:flex;flex-wrap:wrap;gap:12px;align-items:end"><label>Origem <select name="origin"><?php foreach(['todos','manual','iot'] as $v):?><option value="<?=sdH($v)?>" <?=($originFilter??'todos')===$v?'selected':''?>><?=sdH($v)?></option><?php endforeach;?></select></label><label>Prioridade <select name="priority"><?php foreach(['todos','baixa','media','alta','critica'] as $v):?><option value="<?=sdH($v)?>" <?=($priorityFilter??'todos')===$v?'selected':''?>><?=sdH($v)?></option><?php endforeach;?></select></label><label>Status <select name="status"><?php foreach(['todos','aberto','em_atendimento','aguardando','resolvido','fechado'] as $v):?><option value="<?=sdH($v)?>" <?=($statusFilter??'todos')===$v?'selected':''?>><?=sdH($v)?></option><?php endforeach;?></select></label><label>Protocolo, título ou dispositivo <input name="q" maxlength="100" value="<?=sdH($search??'')?>" placeholder="Buscar chamado"></label><label>Responsável <input name="assignee" maxlength="130" value="<?=sdH($assignee??'')?>"></label><label>Prazo SLA <select name="sla"><?php foreach(['todos'=>'Todos','violado'=>'Vencido','proximo'=>'Vence em até 30 min','normal'=>'No prazo'] as $k=>$v):?><option value="<?=sdH($k)?>" <?=($slaFilter??'todos')===$k?'selected':''?>><?=sdH($v)?></option><?php endforeach;?></select></label><button>Aplicar filtros</button><a href="service-desk.php">Limpar</a></form></section><section class="sd-card"><h2>Últimos chamados (até 100)</h2><div class="sd-table-scroll"><table><thead><tr><th>Protocolo</th><th>Origem / título</th><th>Prioridade e SLA</th><th>Status / atualização</th></tr></thead><tbody><?php foreach($tickets as $t):?><tr><td><a href="service-desk-detalhe.php?id=<?=urlencode((string)$t['id'])?>"><?=sdH($t['protocol'])?></a><p><?=sdH($t['created_at'])?></p></td><td><?=sdH($t['origin'])?><p><?=sdH($t['title'])?></p></td><td><?=sdH($t['priority'])?><p>Resposta até <?=sdH($t['sla']['response_deadline'])?></p><p>Resolução até <?=sdH($t['sla']['resolution_deadline'])?></p><?php if($t['urgency']==='violado'):?><strong style="color:#b42318">Prazo excedido</strong><?php elseif($t['urgency']==='proximo'):?><strong style="color:#9a5a00">Prazo próximo</strong><?php endif;?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=sdH($_SESSION['sd_admin_csrf'])?>"><input type="hidden" name="id" value="<?=sdH($t['id'])?>"><select name="status"><?php foreach(['aberto','em_atendimento','aguardando','resolvido','fechado'] as $status):?><option value="<?=$status?>" <?=$status===$t['status']?'selected':''?>><?=$status?></option><?php endforeach;?></select><input name="assigned_to" placeholder="Responsável" maxlength="130" value="<?=sdH($t['assigned_to'])?>"><input name="note" placeholder="Nota para auditoria" maxlength="3000"><button>Salvar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><p><a href="service-desk-regras.php">Configurar regras IoT →</a> · <a href="service-desk-export.php">Exportar chamados CSV</a></p></main><?php include __DIR__.'/footer.php'; ?></body></html>